  background-color: #f3f4f6;
  border-color: #9ca3af;
}

.pagination__button:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.pagination__button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

